/**
 * Python-flavoured exception objects.
 *
 * The reference program is a CPython script, so failures surface as a
 * traceback on stderr followed by exit status 1.  These classes carry the
 * Python exception name plus the pre-rendered stack frames so `test2.mjs`
 * can reproduce that shape.
 */

/** Base class: knows its Python type name and the frames to print. */
export class PyError extends Error {
  constructor(pyType, message, frames = []) {
    super(message);
    this.pyType = pyType;
    this.frames = frames;
  }

  /** `ValueError: message` — the final line of a Python traceback. */
  get pyLine() {
    return this.message === '' ? this.pyType : `${this.pyType}: ${this.message}`;
  }
}

export class ValueError extends PyError {
  constructor(message, frames) {
    super('ValueError', message, frames);
  }
}

/** `UnicodeError` — raised by the idna/punycode codecs. */
export class UnicodeError extends PyError {
  constructor(message, frames) {
    super('UnicodeError', message, frames);
  }
}

/**
 * Attach traceback frames to an exception on its way out of a call, the way
 * CPython grows a traceback as it unwinds.  Frames are prepended so the
 * outermost caller ends up first, matching Python's ordering.
 */
export function addFrames(err, frames) {
  if (err instanceof PyError) {
    err.frames = [...frames, ...err.frames];
  }
  return err;
}

/**
 * repr() of a Python str, used verbatim inside several exception messages.
 * Python prefers single quotes and switches to double quotes only when the
 * value contains a single quote but no double quote.
 */
export function pyRepr(s) {
  const quote = s.includes("'") && !s.includes('"') ? '"' : "'";
  let out = '';
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    if (ch === '\\') out += '\\\\';
    else if (ch === quote) out += '\\' + quote;
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else if (cp < 0x20 || cp === 0x7f) out += '\\x' + cp.toString(16).padStart(2, '0');
    else if (cp >= 0x80 && cp <= 0x9f) out += '\\x' + cp.toString(16).padStart(2, '0');
    else out += ch;
  }
  return quote + out + quote;
}

