/**
 * Small helpers that mirror the CPython string / bytes primitives the URL
 * code leans on.  JavaScript strings are UTF-16 sequences while Python's are
 * code-point sequences, so anything that iterates characters goes through
 * `codePoints()` here.
 */

import { ValueError } from './pyerrors.mjs';

const encoder = new TextEncoder();
/** Lenient decoder: malformed input becomes U+FFFD, like errors='replace'. */
const replaceDecoder = new TextDecoder('utf-8', { fatal: false });

/** Code points of `s`, as an array of single-code-point strings. */
export function codePoints(s) {
  return Array.from(s);
}

/** `s.encode('utf-8')` */
export function utf8Encode(s) {
  return encoder.encode(s);
}

/** `bytes.decode('utf-8', 'replace')` */
export function utf8DecodeReplace(bytes) {
  return replaceDecoder.decode(bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes));
}

/** True when every code point of `s` is below U+0080. */
export function isAscii(s) {
  for (let i = 0; i < s.length; i++) {
    if (s.charCodeAt(i) > 0x7f) return false;
  }
  return true;
}

/**
 * `s.lstrip(WHATWG_C0_CONTROL_OR_SPACE)` as performed by urllib.parse.urlsplit:
 * every leading code point up to and including U+0020 is dropped.
 */
export function lstripC0Space(s) {
  let i = 0;
  while (i < s.length && s.charCodeAt(i) <= 0x20) i++;
  return s.slice(i);
}

/** Remove every tab / CR / LF, matching urlsplit's unsafe-byte scrubbing. */
export function removeUnsafeUrlBytes(s) {
  let out = '';
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (c !== '\t' && c !== '\r' && c !== '\n') out += c;
  }
  return out;
}

/** `str.partition(sep)` → [before, sep|'', after]. */
export function partition(s, sep) {
  const i = s.indexOf(sep);
  if (i === -1) return [s, '', ''];
  return [s.slice(0, i), sep, s.slice(i + sep.length)];
}

/** `str.rpartition(sep)` → [before, sep|'', after]. */
export function rpartition(s, sep) {
  const i = s.lastIndexOf(sep);
  if (i === -1) return ['', '', s];
  return [s.slice(0, i), sep, s.slice(i + sep.length)];
}

/** `str.split(sep, maxsplit)` with Python's maxsplit semantics. */
export function splitN(s, sep, maxsplit) {
  const parts = [];
  let rest = s;
  while (parts.length < maxsplit) {
    const i = rest.indexOf(sep);
    if (i === -1) break;
    parts.push(rest.slice(0, i));
    rest = rest.slice(i + sep.length);
  }
  parts.push(rest);
  return parts;
}

/** `str.rsplit(sep, 1)`. */
export function rsplit1(s, sep) {
  const i = s.lastIndexOf(sep);
  if (i === -1) return [s];
  return [s.slice(0, i), s.slice(i + sep.length)];
}

const ND_RE = /^\p{Nd}$/u;
// Code points that satisfy str.isdigit() but that int() refuses: the
// superscript / subscript / circled digit families (Numeric_Type=Digit).
const DIGIT_NOT_DECIMAL = new Set([
  0x00b2, 0x00b3, 0x00b9, 0x2070, 0x2074, 0x2075, 0x2076, 0x2077, 0x2078, 0x2079,
  0x2080, 0x2081, 0x2082, 0x2083, 0x2084, 0x2085, 0x2086, 0x2087, 0x2088, 0x2089,
  0x2460, 0x2461, 0x2462, 0x2463, 0x2464, 0x2465, 0x2466, 0x2467, 0x2468,
  0x2474, 0x2475, 0x2476, 0x2477, 0x2478, 0x2479, 0x247a, 0x247b, 0x247c,
  0x2488, 0x2489, 0x248a, 0x248b, 0x248c, 0x248d, 0x248e, 0x248f, 0x2490,
]);

/** `str.isdigit()`: decimal digits plus the digit-valued symbols. */
export function pyIsDigit(s) {
  if (s.length === 0) return false;
  for (const ch of codePoints(s)) {
    if (!ND_RE.test(ch) && !DIGIT_NOT_DECIMAL.has(ch.codePointAt(0))) return false;
  }
  return true;
}

/** Numeric value of a single Nd code point (Nd blocks run in tens). */
function decimalValue(ch) {
  let cp = ch.codePointAt(0);
  let value = 0;
  while (value < 10 && ND_RE.test(String.fromCodePoint(cp - 1))) {
    cp -= 1;
    value += 1;
  }
  return value;
}

/** `int(s)` restricted to what furl feeds it: a run of decimal digits. */
export function pyInt(s) {
  const chars = codePoints(s);
  let digits = '';
  for (const ch of chars) {
    if (!ND_RE.test(ch)) {
      throw new ValueError(`invalid literal for int() with base 10: ${JSON.stringify(s)}`);
    }
    digits += String(decimalValue(ch));
  }
  if (digits === '') {
    throw new ValueError(`invalid literal for int() with base 10: ${JSON.stringify(s)}`);
  }
  return Number(digits);
}

