/**
 * urllib.parse's percent-encoding layer.
 *
 * quote()   – bytes outside `always_safe + safe` become %XX (upper-case hex).
 * unquote() – %XX runs are turned back into bytes and decoded as UTF-8 with
 *             errors='replace'; invalid escapes are left alone.  CPython only
 *             unquotes inside ASCII runs, so non-ASCII text passes through
 *             untouched and never merges with neighbouring escapes.
 */

import { utf8Encode, utf8DecodeReplace } from './pystring.mjs';

const ALWAYS_SAFE =
  'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_.-~';

const HEX = '0123456789ABCDEF';

function safeSet(safe) {
  const set = new Set();
  for (const ch of ALWAYS_SAFE) set.add(ch.charCodeAt(0));
  for (const ch of safe) set.add(ch.charCodeAt(0));
  return set;
}

const safeCache = new Map();

function cachedSafeSet(safe) {
  let set = safeCache.get(safe);
  if (set === undefined) {
    set = safeSet(safe);
    safeCache.set(safe, set);
  }
  return set;
}

/** `urllib.parse.quote(s, safe)` */
export function quote(s, safe = '/') {
  const allowed = cachedSafeSet(safe);
  const bytes = utf8Encode(s);
  let out = '';
  for (const byte of bytes) {
    if (allowed.has(byte)) out += String.fromCharCode(byte);
    else out += '%' + HEX[byte >> 4] + HEX[byte & 0x0f];
  }
  return out;
}

/** `urllib.parse.quote_plus(s, safe)` */
export function quotePlus(s, safe = '') {
  if (!s.includes(' ')) return quote(s, safe);
  return quote(s, safe + ' ').split(' ').join('+');
}

function isHexDigit(ch) {
  return (
    (ch >= '0' && ch <= '9') || (ch >= 'a' && ch <= 'f') || (ch >= 'A' && ch <= 'F')
  );
}

/** `unquote_to_bytes()` over a pure-ASCII run. */
function unquoteToBytes(run) {
  const parts = run.split('%');
  const bytes = [];
  for (let i = 0; i < parts[0].length; i++) bytes.push(parts[0].charCodeAt(i));
  for (let i = 1; i < parts.length; i++) {
    const item = parts[i];
    if (item.length >= 2 && isHexDigit(item[0]) && isHexDigit(item[1])) {
      bytes.push(parseInt(item.slice(0, 2), 16));
      for (let j = 2; j < item.length; j++) bytes.push(item.charCodeAt(j));
    } else {
      bytes.push(0x25); // literal '%'
      for (let j = 0; j < item.length; j++) bytes.push(item.charCodeAt(j));
    }
  }
  return Uint8Array.from(bytes);
}

/** `urllib.parse.unquote(s)` with the default utf-8 / replace error handling. */
export function unquote(s) {
  if (!s.includes('%')) return s;
  let out = '';
  let i = 0;
  while (i < s.length) {
    const asciiStart = i;
    while (i < s.length && s.charCodeAt(i) <= 0x7f) i++;
    if (i > asciiStart) out += utf8DecodeReplace(unquoteToBytes(s.slice(asciiStart, i)));
    const rawStart = i;
    while (i < s.length && s.charCodeAt(i) > 0x7f) i++;
    out += s.slice(rawStart, i);
  }
  return out;
}

/** `urllib.parse.unquote_plus(s)` */
export function unquotePlus(s) {
  return unquote(s.split('+').join(' '));
}

