/**
 * Port of CPython's `encodings/idna.py`: nameprep, ToASCII, ToUnicode and the
 * codec-level encode/decode entry points.
 *
 * furl leans on this codec twice: the host setter runs an ACE host back through
 * `decode('idna')` (validating it) and the netloc property runs the stored host
 * through `encode('idna')` when the URL is stringified.
 */

import { PyError, UnicodeError, pyRepr, addFrames } from './pyerrors.mjs';
import { codePoints, isAscii, utf8Encode } from './pystring.mjs';
import { punycodeEncode, punycodeDecode } from './punycode.mjs';
import {
  inTableB1, mapTableB2, inTableC12, inTableC22, inTableC3, inTableC4,
  inTableC5, inTableC6, inTableC7, inTableC8, inTableC9, inTableD1, inTableD2,
} from './stringprep.mjs';

const ACE_PREFIX = 'xn--';

/** Label separators recognised by the codec: U+002E U+3002 U+FF0E U+FF61. */
const DOTS = /[.。．｡]/;

const frame = (line, name) => ({ file: 'encodings/idna.py', line, name });

/** RFC 3491 nameprep. */
export function nameprep(label) {
  // Map: drop table B.1 characters, case-fold through table B.2.
  let mapped = '';
  for (const ch of codePoints(label)) {
    if (inTableB1(ch)) continue;
    mapped += mapTableB2(ch);
  }

  // Normalize.
  let normalized = mapped.normalize('NFKC');

  // Prohibit.
  for (const ch of codePoints(normalized)) {
    if (
      inTableC12(ch) || inTableC22(ch) || inTableC3(ch) || inTableC4(ch) ||
      inTableC5(ch) || inTableC6(ch) || inTableC7(ch) || inTableC8(ch) ||
      inTableC9(ch)
    ) {
      throw new UnicodeError(`Invalid character ${pyRepr(ch)}`, [frame(38, 'nameprep')]);
    }
  }

  // Check bidi.
  const chars = codePoints(normalized);
  const randAL = chars.map(inTableD1);
  if (randAL.some(Boolean)) {
    if (chars.some(inTableD2)) {
      throw new UnicodeError('Violation of BIDI requirement 2', [frame(48, 'nameprep')]);
    }
    if (!randAL[0] || !randAL[randAL.length - 1]) {
      throw new UnicodeError('Violation of BIDI requirement 3', [frame(55, 'nameprep')]);
    }
  }

  return normalized;
}

/** RFC 3490 ToASCII for a single label. */
export function toASCII(label) {
  // Step 1: try ASCII.
  if (isAscii(label)) {
    if (label.length > 0 && label.length < 64) return label;
    throw new UnicodeError('label empty or too long', [frame(67, 'ToASCII')]);
  }

  // Step 2: nameprep.
  let prepped;
  try {
    prepped = nameprep(label);
  } catch (err) {
    throw addFrames(err, [frame(74, 'ToASCII')]);
  }

  // Step 3: UseSTD3ASCIIRules is false.  Step 4: try ASCII again.
  if (isAscii(prepped)) {
    if (prepped.length > 0 && prepped.length < 64) return prepped;
    throw new UnicodeError('label empty or too long', [frame(84, 'ToASCII')]);
  }

  // Step 5: check ACE prefix.
  if (prepped.slice(0, 4).toLowerCase() === ACE_PREFIX) {
    throw new UnicodeError('Label starts with ACE prefix', [frame(91, 'ToASCII')]);
  }

  // Steps 6 and 7: punycode, then prepend the ACE prefix.
  let encoded;
  try {
    encoded = ACE_PREFIX + punycodeEncode(prepped);
  } catch (err) {
    throw addFrames(err, [frame(95, 'ToASCII')]);
  }

  // Step 8: check size.
  if (encoded.length < 64) return encoded;
  throw new UnicodeError('label empty or too long', [frame(101, 'ToASCII')]);
}

/**
 * RFC 3490 ToUnicode for a single label.  `label` is a byte array, mirroring
 * the codec's habit of handing raw bytes to this function.
 */
export function toUnicode(labelBytes) {
  if (labelBytes.length > 1024) {
    throw new UnicodeError('label way too long', [frame(114, 'ToUnicode')]);
  }

  const ascii = labelBytes.every((b) => b < 0x80);
  const asAscii = ascii ? String.fromCharCode(...labelBytes) : null;

  // Step 3: check for the ACE prefix.
  if (!ascii || asAscii.slice(0, 4).toLowerCase() !== ACE_PREFIX) {
    if (!ascii) {
      const pos = labelBytes.findIndex((b) => b >= 0x80);
      throw new PyError(
        'UnicodeDecodeError',
        `'ascii' codec can't decode byte 0x${labelBytes[pos].toString(16)} in position ` +
          `${pos}: ordinal not in range(128)`,
        [frame(136, 'ToUnicode')],
      );
    }
    return asAscii;
  }

  // Steps 4 and 5: strip the prefix and punycode-decode.
  let result;
  try {
    result = punycodeDecode(asAscii.slice(4));
  } catch (err) {
    throw addFrames(err, [frame(140, 'ToUnicode')]);
  }

  // Step 6: re-encode and, step 7, require a round trip.
  let label2;
  try {
    label2 = toASCII(result);
  } catch (err) {
    throw addFrames(err, [frame(142, 'ToUnicode')]);
  }
  if (asAscii.toLowerCase() !== label2) {
    throw new UnicodeError(
      `('IDNA does not round-trip', b'${asAscii}', b'${label2}')`,
      [frame(146, 'ToUnicode')],
    );
  }

  // Step 8: return the result of step 5.
  return result;
}

/** `str.encode('idna')` */
export function idnaCodecEncode(input) {
  if (input === '') return '';

  if (isAscii(input)) {
    // ASCII name: fast path.
    const labels = input.split('.');
    for (const label of labels.slice(0, -1)) {
      if (!(label.length > 0 && label.length < 64)) {
        throw new UnicodeError('label empty or too long', [frame(173, 'encode')]);
      }
    }
    if (labels[labels.length - 1].length >= 64) {
      throw new UnicodeError('label too long', [frame(175, 'encode')]);
    }
    return input;
  }

  const labels = input.split(DOTS);
  let trailingDot = '';
  if (labels.length && labels[labels.length - 1] === '') {
    trailingDot = '.';
    labels.pop();
  }
  const parts = [];
  for (const label of labels) {
    try {
      parts.push(toASCII(label));
    } catch (err) {
      throw addFrames(err, [frame(189, 'encode')]);
    }
  }
  return parts.join('.') + trailingDot;
}

/** `bytes.decode('idna')`, taking the already-encoded UTF-8 form of a str. */
export function idnaCodecDecode(input) {
  const bytes = Array.from(utf8Encode(input));
  if (bytes.length === 0) return '';

  // Fast path when there is no ACE prefix anywhere in the input.
  if (!input.includes(ACE_PREFIX) && bytes.every((b) => b < 0x80)) {
    return input;
  }

  const labels = [];
  let current = [];
  for (const byte of bytes) {
    if (byte === 0x2e) {
      labels.push(current);
      current = [];
    } else {
      current.push(byte);
    }
  }
  labels.push(current);

  let trailingDot = '';
  if (labels.length && labels[labels.length - 1].length === 0) {
    trailingDot = '.';
    labels.pop();
  }

  const parts = [];
  for (const label of labels) {
    try {
      parts.push(toUnicode(label));
    } catch (err) {
      throw addFrames(err, [frame(222, 'decode')]);
    }
  }
  return parts.join('.') + trailingDot;
}

