/**
 * Just enough of CPython's `ipaddress` module to reproduce the accept/reject
 * decisions `urllib.parse._check_bracketed_host()` makes.  Only the verdict is
 * observable, so addresses are validated structurally rather than converted.
 */

const DIGITS = /^[0-9]+$/;
const HEX = /^[0-9A-Fa-f]+$/;

/** `IPv4Address(str)` — 4 dotted decimal octets, no leading zeros. */
export function isIPv4(text) {
  const parts = text.split('.');
  if (parts.length !== 4) return false;
  for (const octet of parts) {
    if (octet.length === 0 || octet.length > 3) return false;
    if (!DIGITS.test(octet)) return false;
    if (octet.length > 1 && octet[0] === '0') return false;
    if (Number(octet) > 255) return false;
  }
  return true;
}

function isHextet(text) {
  return text.length > 0 && text.length <= 4 && HEX.test(text);
}

function isIPv6Body(text) {
  if (text === '') return false;
  const parts = text.split(':');
  if (parts.length < 3) return false;

  // An IPv4-style suffix stands in for the final two hextets.
  if (parts[parts.length - 1].includes('.')) {
    if (!isIPv4(parts.pop())) return false;
    parts.push('0', '0');
  }
  if (parts.length > 9) return false;

  let skipIndex = null;
  for (let i = 1; i < parts.length - 1; i++) {
    if (parts[i] === '') {
      if (skipIndex !== null) return false; // at most one '::'
      skipIndex = i;
    }
  }

  let partsHi;
  let partsLo;
  if (skipIndex !== null) {
    partsHi = skipIndex;
    partsLo = parts.length - skipIndex - 1;
    if (parts[0] === '') {
      partsHi -= 1;
      if (partsHi) return false; // a leading ':' requires '::'
    }
    if (parts[parts.length - 1] === '') {
      partsLo -= 1;
      if (partsLo) return false; // a trailing ':' requires '::'
    }
    if (8 - (partsHi + partsLo) < 1) return false;
  } else {
    if (parts.length !== 8) return false;
    if (parts[0] === '' || parts[parts.length - 1] === '') return false;
    partsHi = parts.length;
    partsLo = 0;
  }

  for (let i = 0; i < partsHi; i++) if (!isHextet(parts[i])) return false;
  for (let i = 1; i <= partsLo; i++) if (!isHextet(parts[parts.length - i])) return false;
  return true;
}

/** `IPv6Address(str)`, including the optional `%scope-id` suffix. */
export function isIPv6(text) {
  if (text.includes('/')) return false;
  const i = text.indexOf('%');
  if (i === -1) return isIPv6Body(text);
  const scopeId = text.slice(i + 1);
  if (scopeId === '' || scopeId.includes('%')) return false;
  return isIPv6Body(text.slice(0, i));
}

/**
 * `ipaddress.ip_address()` reduced to its verdict:
 * 'ipv4', 'ipv6', or null when neither parser accepts the text.
 */
export function ipAddressKind(text) {
  if (isIPv4(text)) return 'ipv4';
  if (isIPv6(text)) return 'ipv6';
  return null;
}

