  if (parts.length > 9) return false;

  let skipIndex = null;
  for (let i = 1; i < parts.length - 1; i++) {
    if (parts[i] === '') {
      if (skipIndex !== null) return false; // at most one '::'
      skipIndex = i;
    }
  }

  let partsHi;
  let partsLo;
  if (skipIndex !== null) {
    partsHi = skipIndex;
    partsLo = parts.length - skipIndex - 1;
    if (parts[0] === '') {
      partsHi -= 1;
      if (partsHi) return false; // a leading ':' requires '::'
    }
    if (parts[parts.length - 1] === '') {
      partsLo -= 1;
      if (partsLo) return false; // a trailing ':' requires '::'
    }
    if (8 - (partsHi + partsLo) < 1) return false;
  } else {
    if (parts.length !== 8) return false;
    if (parts[0] === '' || parts[parts.length - 1] === '') return false;
    partsHi = parts.length;
    partsLo = 0;
  }

  for (let i = 0; i < partsHi; i++) if (!isHextet(parts[i])) return false;
  for (let i = 1; i <= partsLo; i++) if (!isHextet(parts[parts.length - i])) return false;
  return true;
