 * `ipaddress.ip_address()` reduced to its verdict:
 * 'ipv4', 'ipv6', or null when neither parser accepts the text.
 */
export function ipAddressKind(text) {
  if (isIPv4(text)) return 'ipv4';
  if (isIPv6(text)) return 'ipv6';
