/**
 * The slice of `urllib.parse` that furl builds on: `urlsplit()` (including its
 * IPv6 / NFKC netloc validation) and `urlunsplit()`.
 */

import { ValueError, pyRepr } from './pyerrors.mjs';
import {
  lstripC0Space, removeUnsafeUrlBytes, partition, rpartition, splitN, isAscii,
} from './pystring.mjs';
import { ipAddressKind, isIPv4 } from './ipaddress.mjs';

/** Schemes that always render a `//` netloc separator. */
export const USES_NETLOC = new Set([
  '', 'ftp', 'http', 'gopher', 'nntp', 'telnet', 'imap', 'wais', 'file', 'mms',
  'https', 'shttp', 'snews', 'prospero', 'rtsp', 'rtspu', 'rsync', 'svn',
  'svn+ssh', 'sftp', 'nfs', 'git', 'git+ssh', 'ws', 'wss', 'itms-services',
]);

const SCHEME_CHARS =
  'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789+-.';

const frame = (line, name) => ({ file: 'urllib/parse.py', line, name });

function isAsciiAlpha(ch) {
  return (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z');
}

/** `_splitnetloc()`: the netloc runs until the first '/', '?' or '#'. */
function splitNetloc(url, start) {
  let delim = url.length;
  for (const ch of '/?#') {
    const wdelim = url.indexOf(ch, start);
    if (wdelim >= 0 && wdelim < delim) delim = wdelim;
  }
  return [url.slice(start, delim), url.slice(delim)];
}

/** `_check_bracketed_host()` */
function checkBracketedHost(hostname) {
  if (hostname.startsWith('v')) {
    if (!/^v[a-fA-F0-9]+\..+$/.test(hostname)) {
      throw new ValueError('IPvFuture address is invalid', [
        frame(463, '_check_bracketed_host'),
      ]);
    }
    return;
  }
  const kind = ipAddressKind(hostname);
  if (kind === null) {
    throw new ValueError(
      `${pyRepr(hostname)} does not appear to be an IPv4 or IPv6 address`,
      [frame(463, '_check_bracketed_host'), { file: 'ipaddress.py', line: 54, name: 'ip_address' }],
    );
  }
  if (kind === 'ipv4' && isIPv4(hostname)) {
    throw new ValueError('An IPv4 address cannot be in brackets', [
      frame(463, '_check_bracketed_host'),
    ]);
  }
