/** `_check_bracketed_netloc()` — mirrors the splitting done by `_hostinfo`. */
function checkBracketedNetloc(netloc) {
  const hostnameAndPort = rpartition(netloc, '@')[2];
  const [beforeBracket, haveOpenBr, bracketed] = partition(hostnameAndPort, '[');
  let hostname;
  if (haveOpenBr) {
    if (beforeBracket) {
      throw new ValueError('Invalid IPv6 URL', [frame(454, '_check_bracketed_netloc')]);
    }
    const [host, , port] = partition(bracketed, ']');
    hostname = host;
    if (port && !port.startsWith(':')) {
      throw new ValueError('Invalid IPv6 URL', [frame(454, '_check_bracketed_netloc')]);
    }
  } else {
    hostname = partition(hostnameAndPort, ':')[0];
  }
  try {
    checkBracketedHost(hostname);
  } catch (err) {
    if (err.frames) err.frames = [frame(454, '_check_bracketed_netloc'), ...err.frames];
    throw err;
  }
