  if (n === normalized) return;
  for (const ch of '/?#@:') {
    if (normalized.includes(ch)) {
      throw new ValueError(
        `netloc '${netloc}' contains invalid characters under NFKC normalization`,
        [frame(437, 'urlsplit')],
      );
    }
  }
