  if (i > 0 && isAsciiAlpha(url[0])) {
    let ok = true;
    for (const ch of url.slice(1, i)) {
      if (!SCHEME_CHARS.includes(ch)) {
        ok = false;
        break;
      }
    }
    if (ok) {
      scheme = url.slice(0, i).toLowerCase();
      url = url.slice(i + 1);
    }
  }

