  let query = '';
  let fragment = '';

  if (url.startsWith('//')) {
    [netloc, url] = splitNetloc(url, 2);
    const hasOpen = netloc.includes('[');
    const hasClose = netloc.includes(']');
    if ((hasOpen && !hasClose) || (hasClose && !hasOpen)) {
      throw new ValueError('Invalid IPv6 URL', [frame(514, 'urlsplit')]);
    }
    if (hasOpen && hasClose) {
      try {
        checkBracketedNetloc(netloc);
      } catch (err) {
        if (err.frames) err.frames = [frame(516, 'urlsplit'), ...err.frames];
        throw err;
      }
    }
  }
  if (url.includes('#')) {
    [url, fragment] = splitN(url, '#', 1);
  }
  if (url.includes('?')) {
    [url, query] = splitN(url, '?', 1);
  }
