  return { scheme, netloc, path: url, query, fragment };
}

/**
 * `urllib.parse.urlunsplit()`.  A netloc separator is emitted whenever the
 * netloc is non-empty, or the scheme is one that always uses a netloc and the
 * path does not already start with '//'.
 */
export function urlunsplit([scheme, netloc, path, query, fragment]) {
  let url = path;
  if (netloc || (scheme && USES_NETLOC.has(scheme) && url.slice(0, 2) !== '//')) {
    if (url && url.slice(0, 1) !== '/') url = '/' + url;
    url = '//' + (netloc || '') + url;
  }
  if (scheme) url = scheme + ':' + url;
  if (query) url = url + '?' + query;
  if (fragment) url = url + '#' + fragment;
  return url;
}

